use async_trait :: async_trait ; use derive_setters :: Setters ; use forge_domain :: { ContextMessage , Conversation , EventData , EventHandle , RequestPayload , Role , TextMessage , ToolCallArguments , ToolName , } ; use forge_template :: Element ; use tracing :: warn ; use crate :: TemplateEngine ; use forge_domain :: { Context , ContextMessage , ConversationId , MessageEntry , ToolCallArguments , ToolCallFull , } ; use pretty_assertions :: assert_eq ; use super :: * ; impl DoomLoopDetector { const DEFAULT_THRESHOLD : usize = 3 ; # [doc = " Creates a new doom loop detector with the default threshold"] pub fn new () -> Self { Self { threshold : Self :: DEFAULT_THRESHOLD } } # [doc = " Checks conversation history for doom loops using already-recorded tool"] # [doc = " call history in context."] # [doc = ""] # [doc = " This variant is intended for request-phase hooks, where tool call"] # [doc = " results from the previous turn have already been appended to context."] # [doc = ""] # [doc = " Returns Some(count) if a doom loop is detected"] pub fn detect_from_conversation (& self , conversation : & Conversation) -> Option < usize > { let all_signatures = self . extract_tool_signatures (conversation) ; let (_ , count) = self . check_repeating_pattern (& all_signatures) ? ; Some (count) } fn extract_tool_signatures (& self , conversation : & Conversation ,) -> Vec < (ToolName , ToolCallArguments) > { let assistant_messages = conversation . context . as_ref () . map (| ctx | { Self :: extract_assistant_messages (ctx . messages . iter () . map (| entry | & entry . message)) }) . unwrap_or_default () ; assistant_messages . iter () . filter_map (| msg | msg . tool_calls . as_ref ()) . flat_map (| calls | calls . iter ()) . map (| call | (call . name . clone () , call . arguments . clone ())) . collect () } # [doc = " Checks for repeating patterns at the end of the sequence."] fn check_repeating_pattern < T > (& self , sequence : & [T]) -> Option < (usize , usize) > where T : Eq , { if sequence . is_empty () { return None ; } if sequence . len () < self . threshold { return None ; } for pattern_length in 1 .. sequence . len () { let complete_repetitions = self . count_recent_pattern_repetitions (sequence , pattern_length) ; if complete_repetitions >= self . threshold { let pattern_offset = complete_repetitions . checked_mul (pattern_length) ? ; let pattern_start_idx = sequence . len () . checked_sub (pattern_offset) ? ; if sequence . get (pattern_start_idx) . is_some () { return Some ((pattern_start_idx , complete_repetitions)) ; } } } None } # [doc = " Counts how many times a pattern of given length repeats at the END of"] # [doc = " the sequence"] # [doc = ""] # [doc = " This works backwards from the most recent calls to find repeating"] # [doc = " patterns, which allows detecting new patterns even if earlier"] # [doc = " patterns existed. For example, in [1,2,3,1,2,3,4,5,4,5,4,5], this"] # [doc = " will detect [4,5] repeating 3 times."] fn count_recent_pattern_repetitions < T > (& self , sequence : & [T] , pattern_length : usize) -> usize where T : Eq , { if pattern_length == 0 || sequence . len () < pattern_length { return 0 ; } let total_len = sequence . len () ; let mut repetitions = 0 ; let mut check_len = total_len ; if ! total_len . is_multiple_of (pattern_length) { let partial_len = total_len % pattern_length ; if total_len < pattern_length + partial_len { return 0 ; } let pattern_start = total_len - partial_len - pattern_length ; let pattern_end = pattern_start + pattern_length ; let partial_start = total_len - partial_len ; let Some (pattern) = sequence . get (pattern_start .. pattern_end) else { return 0 ; } ; let Some (partial) = sequence . get (partial_start .. total_len) else { return 0 ; } ; let Some (pattern_prefix) = pattern . get (.. partial_len) else { return 0 ; } ; if partial == pattern_prefix { repetitions += 1 ; check_len = total_len - partial_len ; } else { return 0 ; } } if check_len < pattern_length { return repetitions ; } let pattern_start = check_len - pattern_length ; let Some (pattern) = sequence . get (pattern_start .. check_len) else { return repetitions ; } ; repetitions += 1 ; let mut pos = pattern_start ; while pos >= pattern_length { pos -= pattern_length ; let Some (chunk) = sequence . get (pos .. pos + pattern_length) else { break ; } ; if chunk == pattern { repetitions += 1 ; } else { break ; } } repetitions } # [doc = " Extracts assistant messages from context messages"] # [doc = ""] # [doc = " Helper method to filter assistant messages from a conversation context"] pub fn extract_assistant_messages < 'a > (messages : impl Iterator < Item = & 'a ContextMessage > + 'a ,) -> Vec < & 'a TextMessage > { messages . filter_map (| msg | { if let ContextMessage :: Text (text_msg) = msg && text_msg . role == Role :: Assistant { return Some (text_msg) ; } None }) . collect () } }